function combinationSum2(candidates, target) {
  const nums = [...candidates].sort((a, b) => a - b);
  const seen = new Set();
  const result = [];
  for (let mask = 0; mask < 1 << nums.length; mask++) {
    const pick = nums.filter((_, j) => mask & (1 << j));
    const key = pick.join(",");
    if (pick.reduce((s, x) => s + x, 0) === target && !seen.has(key)) {
      seen.add(key);
      result.push(pick);
    }
  }
  return result;
}

