    nums = sorted(candidates)
    result, path = [], []

    def build(start, left):
        if left == 0:
            result.append(path[:])
            return
        for i in range(start, len(nums)):
            if i > start and nums[i] == nums[i - 1]:
                continue                  # same value at the same level: a repeat
            if nums[i] > left:
                break                     # too big, and so is everything after it
            path.append(nums[i])
            build(i + 1, left - nums[i])  # i + 1: each number once
            path.pop()

    build(0, target)
    return result

List<List<Integer>> combinationSum2(int[] candidates, int target) {
    int[] nums = candidates.clone();
    Arrays.sort(nums);
    List<List<Integer>> result = new ArrayList<>();
    build(nums, 0, target, new ArrayList<>(), result);
    return result;
