void build(int[] nums, int start, int left, List<Integer> path, List<List<Integer>> result) {
    if (left == 0) {
        result.add(new ArrayList<>(path));
        return;
    }
    for (int i = start; i < nums.length; i++) {
        if (i > start && nums[i] == nums[i - 1]) continue;   // same value at the same level
        if (nums[i] > left) break;                           // too big, and so is everything after
        path.add(nums[i]);
        build(nums, i + 1, left - nums[i], path, result);    // i + 1: each number once
        path.remove(path.size() - 1);
    }
}

void build(vector<int>& nums, int start, int left, vector<int>& path, vector<vector<int>>& result) {
    if (left == 0) {
        result.push_back(path);
        return;
    }
    for (int i = start; i < (int)nums.size(); i++) {
        if (i > start && nums[i] == nums[i - 1]) continue;   // same value at the same level
        if (nums[i] > left) break;                           // too big, and so is everything after
        path.push_back(nums[i]);
        build(nums, i + 1, left - nums[i], path, result);    // i + 1: each number once
        path.pop_back();
    }
}

